import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Data Security and Storage Hardening in Rook and Ceph | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Data Security and Storage Hardening in Rook and Ceph | Ceph Days NYC 2024","date":"2024-06-18T00:00:00.000Z","updated":"2024-06-19T00:00:00.000Z","tags":["分布式存储","Ceph","安全实践","软件定义存储","Rook"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Data_Security_and_Storage_Hardening_in_Rook_and_Ceph_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Data_Security_and_Storage_Hardening_in_Rook_and_Ceph_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Data_Security_and_Storage_Hardening_in_Rook_and_Ceph_Ceph_Days_NYC_2024.md"};function r(n,a,_,s,d,p){return i(),l("div",null,[...a[0]||(a[0]=[t('<p>在Ceph Days NYC 2024的会议中，主要讨论了Ceph和Rook的存储安全强化和数据安全性问题。以下是会议的关键细节和主要议题的总结：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次会议聚焦于Ceph和Rook的安全性，包括市场趋势、安全实践、产品安全策略以及未来的行动计划。与会者来自IBM和其他公司，共同探讨了Ceph和Rook在安全领域的挑战和解决方案。</p><h3 id="会议关键细节" tabindex="-1">会议关键细节 <a class="header-anchor" href="#会议关键细节" aria-label="Permalink to &quot;会议关键细节&quot;">​</a></h3><ol><li><p><strong>市场规模估计</strong>：</p><ul><li>Ceph的市场规模估计在4.2到6.5 exabytes之间，表明其作为开源软件定义存储产品的巨大影响力。</li></ul></li><li><p><strong>安全实践</strong>：</p><ul><li>介绍了基于威胁模型的安全实践，强调了安全策略的选择应根据不同的威胁场景来定制。</li></ul></li><li><p><strong>IBM产品安全策略</strong>：</p><ul><li>IBM在产品安全方面进行了多项活动，包括安全开发、生命周期管理、漏洞测试等。</li></ul></li><li><p><strong>加密和密钥管理</strong>：</p><ul><li>SEF支持数据静态加密和传输加密，使用DM crypt配置和Messenger版本2.1协议。</li></ul></li><li><p><strong>未来行动计划</strong>：</p><ul><li>继续改进SEF的安全性，包括仪表盘安全和远程功能安全等。</li></ul></li></ol><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h3><ul><li>Ceph和Rook在软件定义存储领域的市场规模和地位。</li><li>如何基于威胁模型选择和实施安全策略。</li><li>IBM如何通过自动化和开源合作提高产品安全性。</li><li>加密和密钥管理在SEF和Rook中的应用。</li></ul><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li>继续支持SEF的多个版本，并与开源社区进行更多合作。</li><li>自动化依赖项的更新，以减少漏洞暴露。</li><li>改进SEF的安全性，包括仪表盘安全和远程功能安全等。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续进行安全开发和生命周期管理活动。</li><li>自动化代码扫描，检测新漏洞，并将修复措施应用到IBM SEF和上游SEF。</li><li>与IBM研究部门合作，探讨量子计算和机密计算的安全性。</li><li>继续支持SEF作为AI和政府客户的存储后端。</li></ul><h3 id="其他资源" tabindex="-1">其他资源 <a class="header-anchor" href="#其他资源" aria-label="Permalink to &quot;其他资源&quot;">​</a></h3><ul><li>Aqua Security提供的关于Kubernetes Secrets的教程。</li><li>Michael Hosenblat的《Hacking Kubernetes》一书中关于存储的章节。</li><li>IBM和Red Hat的产品安全和加固指南。</li></ul><p>这次会议强调了Ceph和Rook在存储安全领域的重要性和未来的发展方向，对于关注这些技术的专业人士来说，是一次宝贵的交流机会。</p>',14)])])}const c=e(o,[["render",r]]);export{u as __pageData,c as default};
